import java.io.InputStream;
import java.io.IOException;
import java.io.PrintWriter;
import java.io.BufferedWriter;
import java.io.OutputStreamWriter;
import java.util.InputMismatchException;

public class Main {
    static final int MOD = 1000000007;
    static int[][][] memo;
    static int N;

    public static void main(String[] args) {
        InputReader in = new InputReader(System.in);
        PrintWriter out = new PrintWriter(new BufferedWriter(new OutputStreamWriter(System.out)));
        int n = in.nextInt();
        out.print(solve(n));
        out.close();
    }

    static int solve(int n) {
        N = 2 * n;
        memo = new int[N + 1][N + 1][2];
        for (int i = 0; i <= N; i++) {
            for (int j = 0; j <= N; j++) {
                memo[i][j][0] = -1;
                memo[i][j][1] = -1;
            }
        }
        memo[0][0][0] = 0;
        memo[0][0][1] = 0;
        return f(N, 0, 0);
    }

    static int f(int i, int j, int k) {
        if (i == 0) {
            return 0;
        }
        if (memo[i][j][k] != -1) {
            return memo[i][j][k];
        }
        int res;
        if (k == 1) {
            res = 0;
            if (i - j >= 2) {
                res = add(res, f(i - 1, j + 1, 0));
            }
            if (j > 0) {
                res = add(res, f(i - 1, j - 1, 0));
            }
        } else {
            res = Math.max(get(i, j, false, false),
                    Math.max(get(i, j, false, true), get(i, j, true, false)));
        }
        memo[i][j][k] = res;
        return res;
    }

    static int get(int i, int j, boolean selectStart, boolean selectEnd) {
        int ret = 0;
        if (i - j >= 2) {
            if (selectStart) {
                ret = add(ret, f(i - 1, j + 1, 1));
                ret = add(ret, 1);
            } else {
                ret = add(ret, f(i - 1, j + 1, 0));
            }
        }
        if (j > 0) {
            if (selectEnd) {
                ret = add(ret, f(i - 1, j - 1, 1));
                ret = add(ret, 1);
            } else {
                ret = add(ret, f(i - 1, j - 1, 0));
            }
        }
        return ret;
    }

    static int add(int a, int b) {
        int res = a + b;
        if (res >= MOD) {
            res -= MOD;
        }
        return res;
    }

    static class InputReader {
        private InputStream stream;
        private byte[] buf = new byte[1024];
        private int curChar;
        private int numChars;

        public InputReader(InputStream stream) {
            this.stream = stream;
        }

        public int read() {
            if (numChars == -1) {
                throw new InputMismatchException();
            }
            if (curChar >= numChars) {
                curChar = 0;
                try {
                    numChars = stream.read(buf);
                } catch (IOException e) {
                    throw new InputMismatchException();
                }
                if (numChars <= 0) {
                    return -1;
                }
            }
            return buf[curChar++];
        }

        public int nextInt() {
            int c = read();
            while (isSpaceChar(c)) {
                c = read();
            }
            int sgn = 1;
            if (c == '-') {
                sgn = -1;
                c = read();
            }
            int res = 0;
            do {
                if (c < '0' || c > '9') {
                    throw new InputMismatchException();
                }
                res *= 10;
                res += c - '0';
                c = read();
            } while (!isSpaceChar(c));
            return res * sgn;
        }

        public boolean isSpaceChar(int c) {
            return c == ' ' || c == '\n' || c == '\r' || c == '\t' || c == -1;
        }
    }
}
